mapper.select:
select * from documents
where id = #{id} and tenant_id = #{tenantId}
limit 1

select * from documents
where knowledge_base_id = #{knowledgeBaseId} and tenant_id = #{tenantId}
order by created_at desc

select *
from documents
where knowledge_base_id = #{knowledgeBaseId}
  and tenant_id = #{tenantId}
  and (
    #{keyword} = ''
    or lower(file_name) like concat('%', lower(#{keyword}), '%')
    or lower(status) like concat('%', lower(#{keyword}), '%')
  )
order by created_at desc
limit #{limit} offset #{offset}

select count(1)
from documents
where knowledge_base_id = #{knowledgeBaseId}
  and tenant_id = #{tenantId}
  and (
    #{keyword} = ''
    or lower(file_name) like concat('%', lower(#{keyword}), '%')
    or lower(status) like concat('%', lower(#{keyword}), '%')
  )
